SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);
SET @cat = (SELECT `id` FROM `categories` WHERE `slug` = 'sports' LIMIT 1);
INSERT INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT @cat, 'Йога', 'Yoga', 'yoga' FROM DUAL WHERE @cat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `subcategories` WHERE `category_id` = @cat AND `slug` = 'yoga');

-- Down Dog — Йога
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'downdogapp.com' OR LOWER(`name`) = 'down dog')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Down Dog', NULL, 'https://www.downdogapp.com', NULL, NULL, 'Застосунок для йоги, який щоразу збирає нову практику під обрані тривалість, рівень, фокус, голос і музику.', 'Yoga app that builds a new practice every time based on your chosen length, level, focus, voice and music.', 'Down Dog не показує записані заздалегідь відео: застосунок щоразу генерує нову послідовність поз під ваші налаштування — тривалість, рівень, тип практики (зокрема пренатальна йога), фокус на частину тіла, темп, голос інструктора й музику. Є також окремі практики пілатесу, HIIT, баре й медитації. Працює на iOS, Android і в браузері, практики можна завантажити для офлайн-занять і вивести на телевізор через Chromecast чи AirPlay. 13 мов із субтитрами. Платна підписка; компанія роздавала безкоштовні членства студентам, викладачам і людям у скруті.', 'Down Dog does not play pre-recorded videos: every time it generates a new pose sequence for your settings, including length, level, practice type (including prenatal yoga), body focus, pace, instructor voice and music. There are also separate Pilates, HIIT, barre and meditation practices. Works on iOS, Android and in the browser; practices can be downloaded for offline use and cast to a TV via Chromecast or AirPlay. 13 languages with subtitles. Paid subscription; the company has given free memberships to students, teachers and people in need.', 'Нова практика щоразу
Налаштування рівня, фокусу, темпу
Пілатес, HIIT, баре, медитація
Офлайн і трансляція на ТБ', 'A new practice every time
Level, focus and pace settings
Pilates, HIIT, barre, meditation
Offline and TV casting', 'Усі, хто займається йогою вдома: новачки, досвідчені практики й люди, яким потрібна м’яка активність', 'Anyone practising yoga at home: beginners, experienced practitioners and people who need gentle activity', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-11-05 00:00:00' FROM DUAL WHERE @new = 1;
