INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Down Dog does not play pre-recorded videos: every time it generates a new pose sequence for your settings, including length, level, practice type (including prenatal yoga), body focus, pace, instructor voice and music. There are also separate Pilates, HIIT, barre and meditation practices. Works on iOS, Android and in the browser; practices can be downloaded for offline use and cast to a TV via Chromecast or AirPlay. 13 languages with subtitles. Paid subscription; the company has given free memberships to students, teachers and people in need.', 'manual' FROM DUAL WHERE @new = 1;
