INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Glo', NULL, 'https://www.glo.com', NULL, NULL, 'Онлайн-студія йоги, пілатесу й медитації: понад 12 000 занять на запит від кількох десятків викладачів.', 'Online yoga, Pilates and meditation studio: 12,000+ on-demand classes from dozens of teachers.', 'Glo — бібліотека з понад 12 000 занять: йога різних стилів, пілатес, медитація, силові тренування, дихальні практики, баре й ходьба. Є багатоденні програми, наприклад серія занять про менопаузу, а річні учасники отримують доступ до живих воркшопів. Працює в застосунку й на сайті. Підписка коштує 245 доларів на рік або 30 доларів на місяць, є 7-денний безкоштовний пробний період.', 'Glo is a library of 12,000+ classes: many yoga styles, Pilates, meditation, strength, breathwork, barre and walking. There are multi-class programs such as a menopause series, and annual members get live workshops. Works in the app and on the web. The subscription costs $245 per year or $30 per month, with a 7-day free trial.', '12 000+ занять на запит
