INSERT INTO search_intents (term_stem, category_id, subcategory_id, weight) SELECT 'йога', (SELECT id FROM categories WHERE slug = 'sports' LIMIT 1), (SELECT s.id FROM subcategories s JOIN categories c ON c.id = s.category_id WHERE c.slug = 'sports' AND s.slug = 'yoga' LIMIT 1), 1 FROM DUAL WHERE (SELECT id FROM categories WHERE slug = 'sports' LIMIT 1) IS NOT NULL AND (SELECT s.id FROM subcategories s JOIN categories c ON c.id = s.category_id WHERE c.slug = 'sports' AND s.slug = 'yoga' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM search_intents si WHERE si.term_stem = 'йога' AND si.category_id <=> (SELECT id FROM categories WHERE slug = 'sports' LIMIT 1) AND si.subcategory_id <=> (SELECT s.id FROM subcategories s JOIN categories c ON c.id = s.category_id WHERE c.slug = 'sports' AND s.slug = 'yoga' LIMIT 1));
